vec2 b = vec2(0.25, 0.065);
vec2 t = q / b;
t.x += mod(floor(t.y), 2.0) * 0.5;
vec2 id = floor(t);
vec2 f = fract(t) * b;
float e = min(min(f.x, b.x - f.x), min(f.y, b.y - f.y));
float joint = (1.0 - smoothstep(0.003, 0.006, e)) * enx_ms(px, 0.05);
float tone = enx_mh(id + 7.3);
float burnt = step(0.82, enx_mh(id + 1.9));
vec3 brick = c * (0.7 + tone * 0.45) * mix(1.0, 0.55, burnt) * (0.94 + enx_mn(q * 80.0) * 0.12 * enx_ms(px, 0.015));
c = mix(brick, c * 0.35, joint);
h += (1.0 - joint) * 0.005;
r = mix(0.55, 0.95, joint) + burnt * 0.1;
